  "check_code": "import hashlib
import json
import zipfile
from pathlib import Path
from xml.etree import ElementTree

from openpyxl import load_workbook


WORKBOOK = "江西生物科技职业学院_2022上半年结构化面试成绩汇总册.xlsx"
SHEET = "考官评分明细"
TARGETS = {"N63", "N185"}
EXPECTED_NOTES = {
    "N63": "计时器重启后复核答题时长",
    "N185": "考官修改分数，统分员双签确认",
}
BASELINE_HASH = "3acb1776640e6aee738a7262f1e12677f9f625923a3379a2828a7950fec95bef"
CHART_PART = "xl/charts/chart1.xml"
CHART_NS = "http://schemas.openxmlformats.org/drawingml/2006/chart"
EXPECTED_CHART_STYLE = "10"


def _path(workspace):
    return Path(workspace) / WORKBOOK


def _cell_content_hash(path):
    wb = load_workbook(path, data_only=False)
    cells = []
    for ws in wb.worksheets:
        for row in ws.iter_rows(min_row=1, max_row=ws.max_row,
                                min_col=1, max_col=ws.max_column):
            for cell in row:
                if ws.title == SHEET and cell.coordinate in TARGETS:
                    continue
                if cell.value is not None:
                    cells.append((ws.title, cell.coordinate, cell.value))
    payload = {
        "sheets": [(ws.title, ws.max_row, ws.max_column) for ws in wb.worksheets],
        "cells": cells,
    }
    wb.close()
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True,
                          default=str, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def _chart_style(path):
    try:
        with zipfile.ZipFile(path) as archive:
            root = ElementTree.fromstring(archive.read(CHART_PART))
        style = root.find(f"{{{CHART_NS}}}style")
        return style.get("val") if style is not None else None
    except (KeyError, OSError, ValueError, zipfile.BadZipFile, ElementTree.ParseError):
        return None


def check_completed_comments_cleared(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "成绩汇总册不存在"}
    wb = load_workbook(path, data_only=False)
    ws = wb[SHEET]
    comments = {coord: ws[coord].comment for coord in TARGETS}
    ok = all(comment is None for comment in comments.values())
    wb.close()
    return {
        "score": int(ok),
        "detail": "目标批注均已清除" if ok else "仍存在目标批注: " + ", ".join(
            coord for coord, comment in comments.items() if comment is not None
        ),
    }


def check_target_notes_preserved(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "成绩汇总册不存在"}
    wb = load_workbook(path, data_only=False)
    ws = wb[SHEET]
    actual = {coord: ws[coord].value for coord in TARGETS}
    wb.close()
    ok = actual == EXPECTED_NOTES
    return {
        "score": int(ok),
        "detail": f"备注值={actual!r}",
    }


def check_unrelated_workbook_content_unchanged(workspace):
    path = _path(workspace)
    if not path.exists():
        return {"score": 0, "detail": "成绩汇总册不存在"}
    actual_hash = _cell_content_hash(path)
    chart_style = _chart_style(path)
    wb = load_workbook(path, data_only=False)
    other_comments = []
    for ws in wb.worksheets:
        for row in ws.iter_rows():
            for cell in row:
                if cell.comment is not None and not (ws.title == SHEET and cell.coordinate in TARGETS):
                    other_comments.append(f"{ws.title}!{cell.coordinate}")
    wb.close()
    ok = (actual_hash == BASELINE_HASH and not other_comments
          and chart_style == EXPECTED_CHART_STYLE)
    details = []
    if actual_hash != BASELINE_HASH:
        details.append(f"非目标单元格内容指纹变化: {actual_hash}")
    if other_comments:
        details.append("发现其他批注: " + ", ".join(other_comments))
    if chart_style != EXPECTED_CHART_STYLE:
        details.append(f"面试总览图表样式变化: {chart_style!r}")
    detail = "非目标单元格公式和值、其他批注及图表样式未变化"
    if details:
        detail = "; ".join(details)
    return {"score": int(ok), "detail": detail}
